Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/amdgpu: avoid double drm_exec_fini() in userq validate
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

When new_addition is true, amdgpu_userq_vm_validate() calls
drm_exec_fini(&exec) before iterating over the collected HMM ranges and
calling amdgpu_ttm_tt_get_user_pages().

If amdgpu_ttm_tt_get_user_pages() fails in that path, the code jumps to
unlock_all and calls drm_exec_fini(&exec) a second time on the same
exec object. drm_exec_fini() is not idempotent: it frees exec->objects
and may also drop exec->contended and finalize the ww acquire context.

Route that error path directly to the range cleanup once exec has
already been finalized.

Fixes: 42f148788469 ("drm/amdgpu/userqueue: validate userptrs for userqueues")
Issue found using a prototype static analysis tool
and confirmed by code review.

Reviewed-by: Christian König <christian.koenig@amd.com>
Signed-off-by: Hongyan Xu <getshell@seu.edu.cn>
Signed-off-by: Slavin Liu <220245772@seu.edu.cn>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>
(cherry picked from commit 2802952e4a07306da6ebe813ff1acacc5691851a)

Here is the root cause:
The function `amdgpu_userq_vm_validate()` prematurely calls `drm_exec_fini(&exec)` when `new_addition` is true, before iterating over HMM ranges. If a subsequent call to `amdgpu_ttm_tt_get_user_pages()` fails, the code jumps to the `unlock_all` label, which calls `drm_exec_fini(&exec)` a second time on the same exec object. Since `drm_exec_fini()` is not idempotent (it frees internal structures), this double finalization causes undefined behavior, such as use-after-free or memory corruption.

Here is the patch:
 /* Make sure the whole VM is ready to be used */
 static int
 amdgpu_userq_vm_validate(struct amdgpu_userq_mgr *uq_mgr)
 {
 	struct amdgpu_fpriv *fpriv = uq_mgr_to_fpriv(uq_mgr);
 	bool invalidated = false, new_addition = false;
 	struct ttm_operation_ctx ctx = { true, false };
 	struct amdgpu_device *adev = uq_mgr->adev;
 	struct amdgpu_hmm_range *range;
 	struct amdgpu_vm *vm = &fpriv->vm;
 	unsigned long key, tmp_key;
 	struct amdgpu_bo_va *bo_va;
 	struct amdgpu_bo *bo;
 	struct drm_exec exec;
 	struct xarray xa;
 	int ret;

 	xa_init(&xa);

 retry_lock:
 	drm_exec_init(&exec, DRM_EXEC_IGNORE_DUPLICATES, 0);
 	drm_exec_until_all_locked(&exec) {
 		ret = amdgpu_vm_lock_pd(vm, &exec, 1);
 		drm_exec_retry_on_contention(&exec);
 		if (unlikely(ret))
 			goto unlock_all;

 		ret = amdgpu_vm_lock_done_list(vm, &exec, 1);
 		drm_exec_retry_on_contention(&exec);
 		if (unlikely(ret))
 			goto unlock_all;

 		/* This validates PDs, PTs and per VM BOs */
 		ret = amdgpu_vm_validate(adev, vm, NULL,
 					 amdgpu_userq_validate_vm,
 					 NULL);
 		if (unlikely(ret))
 			goto unlock_all;

 		/* This locks and validates the remaining evicted BOs */
 		ret = amdgpu_userq_bo_validate(adev, &exec, vm);
 		drm_exec_retry_on_contention(&exec);
 		if (unlikely(ret))
 			goto unlock_all;
 	}

 	if (invalidated) {
 		xa_for_each(&xa, tmp_key, range) {
 			bo = range->bo;
 			amdgpu_bo_placement_from_domain(bo, AMDGPU_GEM_DOMAIN_CPU);
 			ret = ttm_bo_validate(&bo->tbo, &bo->placement, &ctx);
 			if (ret)
 				goto unlock_all;

 			amdgpu_ttm_tt_set_user_pages(bo->tbo.ttm, range);

 			amdgpu_bo_placement_from_domain(bo, AMDGPU_GEM_DOMAIN_GTT);
 			ret = ttm_bo_validate(&bo->tbo, &bo->placement, &ctx);
 			if (ret)
 				goto unlock_all;
 		}
 		invalidated = false;
 	}

 	ret = amdgpu_vm_handle_moved(adev, vm, NULL);
 	if (ret)
 		goto unlock_all;

 	key = 0;
 	/* Validate User Ptr BOs */
 	list_for_each_entry(bo_va, &vm->done, base.vm_status) {
 		bo = bo_va->base.bo;
 		if (!bo)
 			continue;

 		if (!amdgpu_ttm_tt_is_userptr(bo->tbo.ttm))
 			continue;

 		range = xa_load(&xa, key);
 		if (range && range->bo != bo) {
 			xa_erase(&xa, key);
 			amdgpu_hmm_range_free(range);
 			range = NULL;
 		}

 		if (!range) {
 			range = amdgpu_hmm_range_alloc(bo);
 			if (!range) {
 				ret = -ENOMEM;
 				goto unlock_all;
 			}

 			xa_store(&xa, key, range, GFP_KERNEL);
 			new_addition = true;
 		}
 		key++;
 	}

 	if (new_addition) {
 		drm_exec_fini(&exec);
 		xa_for_each(&xa, tmp_key, range) {
 			if (!range)
 				continue;
 			bo = range->bo;
 			ret = amdgpu_ttm_tt_get_user_pages(bo, range);
 			if (ret)
-				goto unlock_all;
+				goto free_ranges;
 		}

 		invalidated = true;
 		new_addition = false;
 		goto retry_lock;
 	}

 	ret = amdgpu_vm_update_pdes(adev, vm, false);
 	if (ret)
 		goto unlock_all;

 	/*
 	 * We need to wait for all VM updates to finish before restarting the
 	 * queues. Using the done list like that is now ok since everything is
 	 * locked in place.
 	 */
 	list_for_each_entry(bo_va, &vm->done, base.vm_status)
 		dma_fence_wait(bo_va->last_pt_update, false);
 	dma_fence_wait(vm->last_update, false);

 	ret = amdgpu_evf_mgr_rearm(&fpriv->evf_mgr, &exec);
 	if (ret)
 		drm_file_err(uq_mgr->file, "Failed to replace eviction fence\n");

 unlock_all:
 	drm_exec_fini(&exec);
+free_ranges:
 	xa_for_each(&xa, tmp_key, range) {
 		if (!range)
 			continue;
 		bo = range->bo;
 		amdgpu_hmm_range_free(range);
 	}
 	xa_destroy(&xa);
 	return ret;
 }



